import gurobipy as gp
from gurobipy import GRB

model = gp.Model(env=env)

jobs = [1, 2, 3]
machines = [1, 2]
proces_time = [[1, 3], [2, 2], [3, 1]]

# Create variables for start times
S = {}
for j in jobs:
    for m in machines:
        S[(j, m)] = model.addVar(lb=0, name=f"S_{j}_{m}")

# Create before variables
before = {}
for i in jobs:
    for j in jobs:
        if i != j:
            before[(i, j)] = model.addVar(vtype=GRB.BINARY, name=f"before_{i}_{j}")

# Constraints for before variables
for i in jobs:
    for j in jobs:
        if i != j:
            model.addConstr(before[(i, j)] + before[(j, i)] == 1)

# Constraints for machine order
M = 1e6
for m in machines:
    for i in jobs:
        for j in jobs:
            if i != j:
                model.addConstr(S[(j, m)] >= S[(i, m)] + proces_time[i-1][m-1] - M * (1 - before[(i, j)]))

# Constraints for sequence between machines
for j in jobs:
    for idx, m in enumerate(machines):
        if idx < len(machines) - 1:
            next_m = machines[idx + 1]
            model.addConstr(S[(j, next_m)] >= S[(j, m)] + proces_time[j-1][m-1])

# Makespan variable
makespan = model.addVar(name="makespan")
for j in jobs:
    for m in machines:
        model.addConstr(makespan >= S[(j, m)] + proces_time[j-1][m-1])

model.setObjective(makespan, GRB.MINIMIZE)
model.optimize()

if model.Status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.ObjVal:.17g}")
```

